#include "SimCore.h"
#include "SimArchive.h"
#include "Banking.h"
namespace CoISim {
void FSimulation::PublishEconomy(FSnapshot& Out) const {
 int64 Money=0,Reserved=0,Arrears=0,Moving=0,Planned=0;for(const auto& A:State.Accounts){Money+=A.BalanceCents;Reserved+=A.ReservedCents;}for(const auto& S:State.Warehouses)Arrears+=S.ArrearsCents;for(const auto& V:State.Vehicles)Arrears+=V.ArrearsCents;for(const auto& F:State.Facilities)Arrears+=F.OperatingArrearsCents;for(const auto& I:State.Inventories)Arrears+=I.RentArrearsCents;for(const auto& T:State.Transports){Moving+=T.Status==TEXT("moving");Planned+=T.Status==TEXT("planned");}
 Out.EconomySummary=FString::Printf(TEXT("AP05 | Geldbilanz: %lld / %lld Cent\nReserviert: %lld | Rückstände: %lld\nTransporte: %lld geplant, %lld unterwegs"),Money,State.InitialMoneyCents+State.DeveloperMoneySources-State.DeveloperMoneySinks+BankMoneyChange(State.Bank),Reserved,Arrears,Planned,Moving);
 if(Scenario.Economy.Bank.Enabled){const auto& B=State.Bank;const auto& Q=Scenario.Economy.Bank;int64 Claims=0,Debt=0,DebtArrears=0,Real=0;for(const auto& L:State.Loans){Claims+=L.OutstandingCents-L.WrittenOffCents;Debt+=L.OutstandingCents+L.AccruedInterestCents;}for(const auto& D:State.DebtDues){DebtArrears+=D.PrincipalCents-D.PrincipalPaidCents+D.InterestCents-D.InterestPaidCents;Debt+=D.InterestCents-D.InterestPaidCents;}for(const auto& A:State.AccountingAssets)if(A.Known)Real+=A.ValueCents;for(const auto& I:State.Inventories)Real+=I.BookValueCents;Out.EconomySummary+=FString::Printf(TEXT("\nAP09.5: Einlagen %lld | Nettobankforderungen %lld | Schuldnerverpflichtungen %lld | Rückstände %lld Cent\nKreditschöpfung +%lld | Tilgung -%lld | Zinsen -%lld | Banklöhne +%lld | Bankbetrieb +%lld Cent\nEröffnungsgegenposten %lld | Bankeigenkapital %lld | Erträge einbehalten %lld | Abschreibung %lld | Reale Assets (bekannte Buchwerte) %lld Cent\nBankbetrieb offen %lld Cent | Bankausgaben nur aus gedecktem Ertragsanteil, keine Inflationsteuerung"),Money,Claims,Debt,DebtArrears,B.CreatedCents,B.RepaidCents,B.InterestCents,B.WagesCents,B.OperatingCents,Q.OpeningBackingCents,BankEquity(Q,B),B.InterestCents-B.WagesCents-B.OperatingCents,B.WriteOffCents,Real,B.OperatingArrearsCents);}
 Out.EconomySummary+=TEXT("\nUI05-Datenvertrag: Haushaltsgruppen genau einmal ihrem Verbrauchshub zuordnen; Regionssummen nicht nochmals über Hubs addieren. Freizeitbedarf ist nicht separat modelliert. Öffentliche Präsenz enthält keine fremden Konten, Bestände oder Einzelaufträge.");
 Out.EconomySummary+=FString::Printf(TEXT("\nUI08: %d organisatorische Handelsvorgänge; keine zusätzlichen Waren-/Geldbestände"),State.Businesses.Num());int32 BusinessShown=0;for(const auto& B:State.Businesses)if(B.OwnerId==Session.PlayerCompanyId&&BusinessShown++<8){Out.EconomySummary+=TEXT("\n")+B.Id+TEXT(" → ")+B.OrderId+TEXT(" · ")+B.OrderStatus+FString::Printf(TEXT(" · %lld/%lld kg"),B.FilledKg,B.RequestedKg);for(const auto& L:B.Legs)Out.EconomySummary+=TEXT("\n  ")+L.Id+TEXT(" · ")+L.Status+FString::Printf(TEXT(" · %lld kg gebucht / %lld angekommen"),L.Kg,L.DeliveredKg);}
 for(const auto& Country:State.Countries)Out.EconomySummary+=FString::Printf(TEXT("\n%s: Bevölkerung %lld, beschäftigt %lld; Modell-BIP seit Start %lld Cent (Endverbrauch + Bestandsänderung + Neubau; keine Geldquelle)"),*Country.Id,Country.Population,Country.Employed,Country.ModelGdpCents);
 for(const auto& G:State.GoodsAudit)Out.EconomySummary+=FString::Printf(TEXT("\n%s: Start %lld + Prod %lld - Input %lld - Kons %lld - Verderb %lld"),*G.Id.RightChop(5),G.InitialKg,G.ProducedKg,G.InputKg,G.ConsumedKg,G.SpoiledKg);
 if(State.DeveloperModified){Out.EconomySummary+=FString::Printf(TEXT("\nENTWICKLEREINGRIFFE: Geldquellen +%lld / Geldsenken -%lld Cent"),State.DeveloperMoneySources,State.DeveloperMoneySinks);for(const auto& G:State.GoodsAudit)if(G.DeveloperAddedKg)Out.EconomySummary+=FString::Printf(TEXT("\nEntwicklerquelle %s +%lld kg (separat von Produktion)"),*G.Id,G.DeveloperAddedKg);}
 for(const auto& P:Scenario.Definitions.Places){const auto* Region=Find(Scenario.Definitions.Regions,P.RegionId);FString Text=TEXT("\n\nMARKT (Cent/kg, kg)\nAbholort und Lager bleiben verbindlich.");
  for(const auto& G:Scenario.Definitions.Goods){int64 Bid=0,Ask=0,BQ=0,AQ=0;for(const auto& O:State.Orders)if(O.Status==TEXT("open")&&O.MarketId==Region->MarketId&&O.GoodId==G.Id){if(O.Side==TEXT("buy")){if(O.LimitCentsPerKg>Bid){Bid=O.LimitCentsPerKg;BQ=0;}if(O.LimitCentsPerKg==Bid)BQ+=O.RemainingKg;}else {if(!Ask||O.LimitCentsPerKg<Ask){Ask=O.LimitCentsPerKg;AQ=0;}if(O.LimitCentsPerKg==Ask)AQ+=O.RemainingKg;}}
   Text+=FString::Printf(TEXT("\n\n%s\nGebot %s | Angebot %s"),*G.Name,*(Bid?FString::Printf(TEXT("%lld (%lld kg)"),Bid,BQ):TEXT("keines")),*(Ask?FString::Printf(TEXT("%lld (%lld kg)"),Ask,AQ):TEXT("keines")));
   const auto* M=Find(State.MarketTotals,Region->MarketId+TEXT("|")+G.Id);if(M){int64 Age=State.EconomyHour-M->LastHour;Text+=FString::Printf(TEXT("\nLetzter Abschluss %lld; Alter %lld h%s\nUmsatz heute %lld kg; gesamt %lld kg"),M->LastPrice,Age,Age>=Scenario.Economy.OrderLifetimeHours?TEXT(" (veraltet)"):TEXT(""),M->Day==State.EconomyHour/24?M->DayVolumeKg:0,M->VolumeKg);}else Text+=TEXT("\nKein Abschluss; kein Marktpreis. Umsatz 0.");
   int Shown=0;for(const auto& O:State.Orders)if(O.Status==TEXT("open")&&O.MarketId==Region->MarketId&&O.GoodId==G.Id&&Shown++<2)Text+=FString::Printf(TEXT("\n%s: %s; %lld kg; gebunden %lld Cent/%lld kg"),*O.Side,*O.StorageId,O.RemainingKg,O.ReservedCents,O.ReservedKg);
  }
  Text+=TEXT("\n\nHAUSHALTE (Cent / kg)");for(const auto& D:Scenario.Definitions.Groups)if(D.RegionId==P.RegionId){const auto* G=Find(State.Groups,D.Id);const auto* A=Find(State.Accounts,G->AccountId);Text+=FString::Printf(TEXT("\n\n%s: %lld Personen, %lld beschäftigt\nGeld %lld; gebunden %lld\nLohn/Tag %lld; Budget %lld; ausgegeben %lld"),*D.IncomeBand,G->Population,G->Employed,A->BalanceCents,A->ReservedCents,G->DailyIncomeCents,G->BudgetCents,G->DailySpentCents);for(const auto& U:G->UnmetNeed)Text+=FString::Printf(TEXT("\nFehlbedarf heute %s %lld"),*U.GoodId.RightChop(5),U.Kg);for(const auto& C:G->Consumed)if(C.Kg)Text+=FString::Printf(TEXT("\nKonsum gesamt %s %lld"),*C.GoodId.RightChop(5),C.Kg);for(const auto& U:G->MissedNeed)if(U.Kg)Text+=FString::Printf(TEXT("\nFrühere Fehlmenge %s %lld"),*U.GoodId.RightChop(5),U.Kg);}
  Text+=TEXT("\n\nBETRIEBE / LAGER");for(const auto& F:State.Facilities)if(F.CityId==P.Id){const auto* C=Find(State.Accounts,ActorAccount(F.OwnerId));Text+=FString::Printf(TEXT("\n%s: Kasse %lld, gebunden %lld\nAuslastung %lld/1000; ungedeckte Stellen %lld\nBetriebsrückstand %lld"),*F.Id,C->BalanceCents,C->ReservedCents,F.UtilizationPermille,F.UnfundedJobs,F.OperatingArrearsCents);}for(const auto& W:State.Warehouses)if(W.CityId==P.Id)Text+=FString::Printf(TEXT("\n%s: %lld + %lld reserviert / %lld Punkte; Rückstand %lld"),*W.Id,UsedStorage(W.Id),W.ReservedIncomingPoints,Find(Scenario.Definitions.WarehouseTypes,W.TypeId)->CapacityPoints,W.ArrearsCents);
  Text+=TEXT("\n\nTRANSPORT");int ShownJobs=0;for(int32 Index=State.Transports.Num()-1;Index>=0&&ShownJobs<8;--Index){const auto& J=State.Transports[Index];if(J.FromCityId!=P.Id&&J.ToCityId!=P.Id)continue;++ShownJobs;Text+=FString::Printf(TEXT("\n%s %s: %lld kg; %lld Cent\n%s -> %s; Ankunft h%lld"),*J.Id,*J.Status,J.Kg,J.CostCents,*J.FromCityId,*J.ToCityId,J.ArrivalStep);}
  Out.EconomyDetails.Add(P.Id,Text);Out.EconomyDetails.Add(P.RegionId,Text);
 }
}
}
